def reconstruct_context(graph):
 assignments=json.loads((HERE.parent/'all-node-assignments.json').read_text())['lanes']['canadian-colonial']
 nodes={n['id']:n for n in graph['nodes']};sources={s['id']:s for s in graph['sources']}
 def source_ids(value):
  found=set()
  if isinstance(value,dict):
   for key,item in value.items():
    if key=='source_ids' and isinstance(item,list):found.update(x for x in item if isinstance(x,str))
    else:found.update(source_ids(item))
  elif isinstance(value,list):
   for item in value:found.update(source_ids(item))
  return found
 result=[]
 for row in assignments:
  node=nodes[row['node_id']];edges=[e for e in graph['edges'] if node['id'] in (e['source'],e['target'])]
  ids=source_ids(node)|source_ids(edges)
  result.append(dict(node=node,existing_edges=edges,sources=[sources[sid] for sid in sorted(ids) if sid in sources]))
 return result
def main():
 graph_path=ROOT/'historiography-1920-2000.json';graph=json.loads(graph_path.read_text())
 context=json.loads(CONTEXT.read_text()) if CONTEXT.exists() else reconstruct_context(graph)
 assert len(context)==90 and set(ASSESSMENTS)=={r['node']['id'] for r in context}
 rows=[]
 for record in context:
  node=record['node'];assessment,links=ASSESSMENTS[node['id']];tokens=links.split();edges=record['existing_edges']
  rows.append(dict(node_id=node['id'],label=node['label'],layer=node['layer'],entry_kind=node['entry_kind'],existing_degree=len(edges),
   reviewed_fields=['description (screened excerpts)','existing incident edge endpoints, relationship text and kind','source identity/URL inventory; inherited verification notes selected for named leads'],
   reviewed_source_ids=node.get('source_ids',[]),inherited_context_source_ids=[s['id'] for s in record['sources']],
   known_represented_relations=[dict(id=e['id'],source=e['source'],target=e['target'],kind=e.get('relationship_kind'),directed=e.get('directed'),claim=e['relationship']) for e in edges],
   possible_missing_debts_critiques_reception=assessment,proposal_ids=[t for t in tokens if t.startswith('rea_')],held_case_ids=[t for t in tokens if t.startswith('hold_')],
   read_extent=dict(current_entry_and_inherited_context='Semantic screen of the supplied entry-description excerpts, incident relationship claims and selected inherited source notes; source IDs are an inventory, not a claim to have freshly read every cited body.',fresh_primary_source_ids=[]),
   assessment=assessment,completeness_claim=False))
 report=dict(schema='response_edge_node_review/1',lane='canadian-colonial',baseline_revision=graph['revision_history'][-1]['version'],baseline_commit='2aa5ac9094a82c6d657783a3ff9585218a10d6d6',baseline_graph_sha256=hashlib.sha256(graph_path.read_bytes()).hexdigest(),checked_on='2026-10-25',status='all_90_contexts_screened_primary_proposal_validation_in_progress',nodes_reviewed=len(rows),method='Every assigned node receives a reasoned semantic screen. Degree is recorded for reproduction, never used to infer completeness. Fresh primary passages are separately recorded in proposals.json; no graph edits are made.',rows=rows)
 (HERE/'node-review.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
 print('Wrote reasoned rows:',len(rows))
if __name__=='__main__':main()
